# Implementasi Simulator Alokasi Partisi Consumer Group (Range & Round-Robin Assignor)
class ConsumerGroupCoordinator:
    @staticmethod
    def assign_partitions_round_robin(consumer_ids, partition_ids):
        if not consumer_ids:
            return {}
        assignments = {c: [] for c in consumer_ids}
        # Bagikan partisi secara bergilir (Round-Robin)
        for idx, p in enumerate(partition_ids):
            assigned_c = consumer_ids[idx % len(consumer_ids)]
            assignments[assigned_c].append(p)
        return assignments

# Skenario: Topik dengan 6 partisi (0 s.d. 5)
topic_partitions = [0, 1, 2, 3, 4, 5]

# Fase 1: 2 Consumer aktif di grup
state_1 = ConsumerGroupCoordinator.assign_partitions_round_robin(['C-1', 'C-2'], topic_partitions)
# Fase 2: Skala bertambah -> Consumer C-3 bergabung (Rebalance terjadi!)
state_2 = ConsumerGroupCoordinator.assign_partitions_round_robin(['C-1', 'C-2', 'C-3'], topic_partitions)

print(f'Alokasi Partisi Kafka Consumer Group ({len(topic_partitions)} Partisi):')
print('Fase 1 (2 Konsumen):')
for c, parts in state_1.items():
    print(f'  - {c}: Mengonsumsi Partisi {parts} (Beban: {len(parts)} partisi)')
print('Fase 2 (Pasca-Rebalance, 3 Konsumen):')
for c, parts in state_2.items():
    print(f'  - {c}: Mengonsumsi Partisi {parts} (Beban: {len(parts)} partisi)')
print('Kesimpulan: Beban kerja terbagi seimbang sempurna (2 partisi/konsumen) pasca-rebalance.')

# Demonstrasi Jaminan Pengiriman: At-Least-Once (Duplikasi) vs Exactly-Once (Idempotent Filter)
class DeliverySemanticsSimulator:
    @staticmethod
    def process_at_least_once(incoming_messages_with_retries):
        # At-least-once menerima seluruh pesan tanpa filter duplikat
        processed_ledger = []
        for msg in incoming_messages_with_retries:
            processed_ledger.append(msg['amount'])
        return {'mode': 'At-Least-Once', 'total_amount': sum(processed_ledger), 'entries': len(processed_ledger)}

    @staticmethod
    def process_exactly_once(incoming_messages_with_retries):
        # Exactly-once menyaring pesan duplikat berdasarkan Message ID unik
        processed_ledger = []
        seen_message_ids = set()

        for msg in incoming_messages_with_retries:
            m_id = msg['msg_id']
            if m_id not in seen_message_ids:
                seen_message_ids.add(m_id)
                processed_ledger.append(msg['amount'])

        return {'mode': 'Exactly-Once', 'total_amount': sum(processed_ledger), 'entries': len(processed_ledger)}

# Skenario: 3 transaksi asli, namun transaksi TX-102 terkirim 3 kali akibat network retry timeout
network_stream = [
    {'msg_id': 'TX-101', 'amount': 100.0},
    {'msg_id': 'TX-102', 'amount': 250.0},  # Kiriman pertama
    {'msg_id': 'TX-102', 'amount': 250.0},  # Retry duplikat 1
    {'msg_id': 'TX-102', 'amount': 250.0},  # Retry duplikat 2
    {'msg_id': 'TX-103', 'amount': 50.0}
]

alo_res = DeliverySemanticsSimulator.process_at_least_once(network_stream)
eos_res = DeliverySemanticsSimulator.process_exactly_once(network_stream)

print(f'Evaluasi Semantik Pengiriman Pesan ({len(network_stream)} Pesan Masuk):')
print(f'  1. {alo_res["mode"]} : Total Saldo=${alo_res["total_amount"]:,.2f} ({alo_res["entries"]} entri, Terjadi Overcounting Duplikat!)')
print(f'  2. {eos_res["mode"]}   : Total Saldo=${eos_res["total_amount"]:,.2f} ({eos_res["entries"]} entri, Tepat & Presisi!)')
print('Kesimpulan: EOS mutlak diwajibkan untuk integritas transaksi analitik dan finansial.')

# Implementasi Simulator Idempotent Producer & Broker Sequence Tracking Engine
class BrokerIdempotenceGuard:
    def __init__(self):
        # Pelacakan sequence terakhir: {(PID, partition): last_sequence_number}
        self.pid_sequences = {}
        self.committed_log = []

    def receive_produce_request(self, pid, partition, sequence_num, payload):
        key = (pid, partition)
        last_seq = self.pid_sequences.get(key, -1)

        if sequence_num == last_seq + 1:
            # Pesan baru terurut valid: Tulis ke log fisik & perbarui state
            self.committed_log.append({'pid': pid, 'seq': sequence_num, 'data': payload})
            self.pid_sequences[key] = sequence_num
            return {'status': 'COMMITTED', 'ack': True, 'action': 'WRITE_TO_LOG'}

        elif sequence_num <= last_seq:
            # Deteksi DUPLIKAT: Abaikan penulisan disk, kembalikan ACK sukses!
            return {'status': 'DUPLICATE_IGNORED', 'ack': True, 'action': 'ACK_ONLY_NO_WRITE'}

        else:
            # Terjadi celah urutan pesan (Out of order)
            return {'status': 'OUT_OF_ORDER_ERROR', 'ack': False, 'action': 'REJECT'}

broker_guard = BrokerIdempotenceGuard()
producer_id = 998877

# 1. Produser kirim pesan Seq 0 (Berhasil)
req1 = broker_guard.receive_produce_request(producer_id, partition=0, sequence_num=0, payload='Order Created')
# 2. Produser kirim pesan Seq 1 (Berhasil)
req2 = broker_guard.receive_produce_request(producer_id, partition=0, sequence_num=1, payload='Payment Success')
# 3. Jaringan putus saat kirim ACK: Produser retry mengirim ulang Seq 1
req3_retry = broker_guard.receive_produce_request(producer_id, partition=0, sequence_num=1, payload='Payment Success')

print('Simulasi Mekanisme Idempotent Producer Kafka:')
print(f'  Pengiriman Seq 0 : Status={req1["status"]} -> {req1["action"]}')
print(f'  Pengiriman Seq 1 : Status={req2["status"]} -> {req2["action"]}')
print(f'  Retry Seq 1 (Dup): Status={req3_retry["status"]} -> {req3_retry["action"]}')
print(f'  Total Record di Log Fisik: {len(broker_guard.committed_log)} record (Zero Duplication!)')
print('Kesimpulan: Idempotent producer mengamankan log dari duplikasi akibat gangguan jaringan.')
